problems = [{'id': 'DRAGON-70', 'title': 'Chữ Số Thập Phân Thứ 70', 'chapter': 'Phần VII. Xử lý chữ số', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào hai số nguyên dương $a$ và $b$. Hãy tìm và in ra chữ số thập phân thứ 70 sau dấu phẩy của phép chia $a / b$.', 'input_format': 'Một dòng duy nhất chứa hai số nguyên dương $a$ và $b$ ($1 \\le a, b \\le 10^6$), cách nhau bởi một khoảng trắng.', 'output_format': 'In ra một chữ số duy nhất (từ 0 đến 9).', 'constraints': '$1 \\le a, b \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '10 3', 'sample_output': '3', 'hints': 'Mô phỏng phép chia đặt tính tay: lấy phần dư $r = a \\% b$, lặp 70 lần: $r = r \\times 10$, chữ số $d = r // b$, sau đó cập nhật $r = r \\% b$.', 'python_starter': "# Bí kíp luyện rồng - Chữ Số Thập Phân Thứ 70\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Chữ Số Thập Phân Thứ 70\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    a, b = int(tokens[0]), int(tokens[1])\n    r = a % b\n    d = 0\n    for _ in range(70):\n        r *= 10\n        d = r // b\n        r %= b\n    print(d)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long a, b;\n    if (scanf("%lld %lld", &a, &b) == 2) {\n        long long r = a % b;\n        int d = 0;\n        for (int i = 0; i < 70; i++) {\n            r *= 10;\n            d = r / b;\n            r %= b;\n        }\n        printf("%d\\n", d);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Các kiểu dữ liệu số thực như `double` hay `float` chỉ có độ chính xác khoảng 15-17 chữ số thập phân nên không thể lưu trực tiếp đến chữ số thứ 70. Ta áp dụng phương pháp chia tay cơ bản ở tiểu học: sau phần nguyên, mỗi lần hạ một chữ số 0 tương ứng với $r = r \\times 10$, chữ số thương tiếp theo là $r // b$, và số dư mới là $r \\% b$. Lặp lại đúng 70 lần để thu được chữ số thập phân thứ 70.\\n- **Độ phức tạp:** Thời gian $O(1)$ (chỉ 70 bước), Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 10/3)', 'input_data': '10 3\n', 'expected_output': '3\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Phép chia hữu hạn (1/2 = 0.5000...)', 'input_data': '1 2\n', 'expected_output': '0\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Phân số 1/7 có chu kỳ 6 (142857)', 'input_data': '1 7\n', 'expected_output': '8\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Số Pi xấp xỉ 22/7', 'input_data': '22 7\n', 'expected_output': '8\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Mẫu số lớn', 'input_data': '355 113\n', 'expected_output': '9\n'}]}, {'id': 'DRAGON-71', 'title': 'Kiểm Tra Số Chính Phương', 'chapter': 'Phần II. Toán học số chính phương', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 71 trong Bí kíp luyện rồng:\n\nSố chính phương là bình phương của một số nguyên. Nhập vào 1 số nguyên dương $n$ ($0 \\le n \\le 10^9$). Hãy kiểm tra xem $n$ có phải là số chính phương hay không.\n\nIn ra `YES` nếu đúng, ngược lại in ra `NO`.', 'input_format': 'Một số nguyên dương $n$ ($0 \\le n \\le 10^9$).', 'output_format': 'In ra `YES` hoặc `NO`.', 'constraints': '$0 \\le n \\le 10^9$.', 'sample_input': '9', 'sample_output': 'YES', 'hints': 'Lấy căn bậc hai nguyên $r = \\lfloor\\sqrt{n}\\rfloor$. Kiểm tra xem $r \\times r == n$ hay không.', 'python_starter': "# Bí kíp luyện rồng - Bài 71: Số Chính Phương\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 71: Số Chính Phương\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\nimport math\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        n = int(line)\n        if n < 0:\n            print("NO")\n            return\n        r = int(math.isqrt(n))\n        print("YES" if r * r == n else "NO")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <math.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        if (n < 0) {\n            printf("NO\\n");\n            return 0;\n        }\n        long long r = (long long)(sqrt(n) + 1e-9);\n        if (r * r == n) printf("YES\\n");\n        else printf("NO\\n");\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Tìm $r = \\lfloor\\sqrt{n}\\rfloor$. Nếu $r \\times r == n$ thì $n$ là số chính phương.\n- Độ phức tạp thời gian: $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (9 -> YES)', 'input_data': '9\n', 'expected_output': 'YES\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (6 -> NO)', 'input_data': '6\n', 'expected_output': 'NO\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (0 -> YES vì 0^2 = 0)', 'input_data': '0\n', 'expected_output': 'YES\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test biên (1 -> YES)', 'input_data': '1\n', 'expected_output': 'YES\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test chính phương lớn (10^9^2 -> 10^8: 100000000 -> YES)', 'input_data': '100000000\n', 'expected_output': 'YES\n'}]}, {'id': 'DRAGON-72', 'title': 'Số Chính Phương #2 (Chính Phương Nhỏ Nhất >= N)', 'chapter': 'Phần V. Bài toán phân tích & Số học', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào số nguyên dương $n$. In ra số chính phương nhỏ nhất lớn hơn hoặc bằng $n$. (Số chính phương là bình phương của một số nguyên).', 'input_format': 'Một dòng duy nhất chứa số nguyên $n$ ($0 \\le n \\le 100000$).', 'output_format': 'In ra số chính phương nhỏ nhất $\\ge n$.', 'constraints': '$0 \\le n \\le 100000$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '6', 'sample_output': '9', 'hints': 'Tính căn bậc hai của $n$. Nếu căn bậc hai bình phương nhỏ hơn $n$, tăng lên 1 đơn vị rồi bình phương lại.', 'python_starter': "# Bí kíp luyện rồng - Số Chính Phương #2\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Số Chính Phương #2\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\nimport math\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    if n <= 0:\n        print(0)\n        return\n    k = math.isqrt(n)\n    if k * k < n:\n        k += 1\n    print(k * k)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <math.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        if (n <= 0) {\n            printf("0\\n");\n            return 0;\n        }\n        long long k = (long long)sqrt(n);\n        if (k * k < n) {\n            k++;\n        }\n        printf("%lld\\n", k * k);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Với $n \\ge 0$, ta tính $k = \\lfloor\\sqrt{n}\\rfloor$. Nếu $k \\times k < n$, thì số chính phương nhỏ nhất $\\ge n$ chính là $(k + 1)^2$. Nếu $k \\times k == n$, thì kết quả chính là $k^2 = n$.\\n- **Độ phức tạp:** Thời gian $O(1)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu n = 6)', 'input_data': '6\n', 'expected_output': '9\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Bản thân n đã là số chính phương', 'input_data': '16\n', 'expected_output': '16\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên n = 0', 'input_data': '0\n', 'expected_output': '0\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test biên n = 1', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Biên trên n = 99999', 'input_data': '99999\n', 'expected_output': '100489\n'}]}, {'id': 'DRAGON-73', 'title': 'Kiểm Tra Số May Mắn (Harshad Number)', 'chapter': 'Phần II. Xử lý số học', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 73 trong Bí kíp luyện rồng:\n\nNhập vào số nguyên dương $n$ ($0 \\le n \\le 10^9$). Kiểm tra xem $n$ có phải là số may mắn không.\n\nMột số $n$ được gọi là số may mắn (Harshad Number) khi và chỉ khi $n$ chia hết cho tổng các chữ số của nó.\n\nIn ra `YES` nếu đúng, ngược lại in ra `NO`.', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra `YES` hoặc `NO`.', 'constraints': '$1 \\le n \\le 10^9$.', 'sample_input': '12', 'sample_output': 'YES', 'hints': 'Tính tổng các chữ số của n. Sau đó kiểm tra $n \\% sum == 0$. Ví dụ $n = 12 \\rightarrow 1+2=3 \\rightarrow 12 \\% 3 == 0 \\rightarrow$ YES.', 'python_starter': "# Bí kíp luyện rồng - Bài 73: Số May Mắn\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 73: Số May Mắn\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        n = int(line)\n        s = sum(int(c) for c in str(n))\n        if s > 0 and n % s == 0:\n            print("YES")\n        else:\n            print("NO")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long tmp = n;\n        long long sum = 0;\n        while (tmp > 0) {\n            sum += tmp % 10;\n            tmp /= 10;\n        }\n        if (sum > 0 && n % sum == 0) printf("YES\\n");\n        else printf("NO\\n");\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Tính tổng các chữ số $S$ của $n$.\n- Kiểm tra điều kiện $n \\pmod S == 0$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (12 -> YES)', 'input_data': '12\n', 'expected_output': 'YES\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (13 -> NO)', 'input_data': '13\n', 'expected_output': 'NO\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (1 chữ số: 7 -> 7%7==0 -> YES)', 'input_data': '7\n', 'expected_output': 'YES\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test 18 (18 chia hết cho 9 -> YES)', 'input_data': '18\n', 'expected_output': 'YES\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test n = 1000000000 (10^9 chia hết cho 1 -> YES)', 'input_data': '1000000000\n', 'expected_output': 'YES\n'}]}, {'id': 'DRAGON-74', 'title': 'Đếm #1 (Số Lượng Số Chính Phương <= N)', 'chapter': 'Phần V. Bài toán phân tích & Số học', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào số nguyên dương $n$. Đếm xem có bao nhiêu số chính phương dương nhỏ hơn hoặc bằng $n$ (các số có dạng $k^2$ với $k \\ge 1, k^2 \\le n$).', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra số lượng số chính phương $\\le n$.', 'constraints': '$1 \\le n \\le 10^9$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '10', 'sample_output': '3', 'hints': 'Số các số chính phương $1^2, 2^2, \\dots, k^2 \\le n$ chính bằng $\\lfloor\\sqrt{n}\\rfloor$.', 'python_starter': "# Bí kíp luyện rồng - Đếm #1\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Đếm #1\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\nimport math\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    print(math.isqrt(n))\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <math.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long ans = (long long)sqrt(n);\n        printf("%lld\\n", ans);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Các số chính phương dương nhỏ hơn hoặc bằng $n$ là $1^2, 2^2, 3^2, \\dots, k^2$ với $k^2 \\le n \\iff k \\le \\sqrt{n}$. Do đó số lượng số chính phương cần tìm chính là phần nguyên của căn bậc hai của $n$, tức $\\lfloor\\sqrt{n}\\rfloor$.\\n- **Độ phức tạp:** Thời gian $O(1)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu n = 10)', 'input_data': '10\n', 'expected_output': '3\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test n = 1', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Số chính phương (n = 25)', 'input_data': '25\n', 'expected_output': '5\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Gần chính phương (n = 99)', 'input_data': '99\n', 'expected_output': '9\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test n = 10^9', 'input_data': '1000000000\n', 'expected_output': '31622\n'}]}, {'id': 'DRAGON-75', 'title': 'Đếm #2 (Số Lượng Số Nguyên Tố <= N)', 'chapter': 'Phần V. Bài toán phân tích & Số học', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào số nguyên dương $n$. Đếm xem có bao nhiêu số nguyên tố nhỏ hơn hoặc bằng $n$.', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 10^6$).', 'output_format': 'In ra số lượng số nguyên tố $\\le n$.', 'constraints': '$1 \\le n \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '10', 'sample_output': '4', 'hints': 'Sử dụng sàng nguyên tố Eratosthenes để sàng các số nguyên tố tới $n$ một cách nhanh chóng trong $O(n \\log \\log n)$.', 'python_starter': "# Bí kíp luyện rồng - Đếm #2\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Đếm #2\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    if n < 2:\n        print(0)\n        return\n    is_prime = bytearray([1]) * (n + 1)\n    is_prime[0] = is_prime[1] = 0\n    limit = int(n**0.5)\n    for i in range(2, limit + 1):\n        if is_prime[i]:\n            is_prime[i*i : n+1 : i] = bytearray([0]) * len(range(i*i, n+1, i))\n    print(sum(is_prime))\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        if (n < 2) {\n            printf("0\\n");\n            return 0;\n        }\n        char *is_prime = (char*)malloc(n + 1);\n        memset(is_prime, 1, n + 1);\n        is_prime[0] = is_prime[1] = 0;\n        for (int i = 2; i * i <= n; i++) {\n            if (is_prime[i]) {\n                for (int j = i * i; j <= n; j += i) {\n                    is_prime[j] = 0;\n                }\n            }\n        }\n        int count = 0;\n        for (int i = 2; i <= n; i++) {\n            if (is_prime[i]) count++;\n        }\n        printf("%d\\n", count);\n        free(is_prime);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Với $n$ lên tới $10^6$, thuật toán sàng nguyên tố Eratosthenes là tối ưu nhất. Khởi tạo mảng boolean đánh dấu từ 0 đến $n$. Lần lượt gạch đi các bội số của các số nguyên tố từ 2 đến $\\sqrt{n}$. Cuối cùng đếm số lượng vị trí còn được đánh dấu.\\n- **Độ phức tạp:** Thời gian $O(n \\log \\log n)$, Bộ nhớ $O(n)$ (khoảng 1MB).', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu n = 10)', 'input_data': '10\n', 'expected_output': '4\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test không có số nguyên tố (n = 1)', 'input_data': '1\n', 'expected_output': '0\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test số nguyên tố nhỏ nhất (n = 2)', 'input_data': '2\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test n = 100', 'input_data': '100\n', 'expected_output': '25\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test n = 10^6', 'input_data': '1000000\n', 'expected_output': '78498\n'}]}, {'id': 'DRAGON-76', 'title': 'Đếm #3 (Số Chính Phương Trong Dãy)', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào dãy số $A$ có $n$ phần tử. Đếm xem trong dãy $A$ có bao nhiêu số là số chính phương.', 'input_format': 'Dòng 1: Số nguyên dương $n$ ($1 \\le n \\le 100$).\\nDòng 2: $n$ số nguyên dương $a_i$ ($1 \\le a_i \\le 10^6$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra số lượng số chính phương có trong dãy $A$.', 'constraints': '$1 \\le n \\le 100$\\n$1 \\le a_i \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '5\n1 2 3 4 5', 'sample_output': '2', 'hints': 'Kiểm tra từng phần tử $x$: tính $k = \\lfloor\\sqrt{x}\\rfloor$, nếu $k \\times k == x$ thì $x$ là số chính phương.', 'python_starter': "# Bí kíp luyện rồng - Đếm #3\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Đếm #3\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\nimport math\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n = int(tokens[0])\n    nums = [int(x) for x in tokens[1:n+1]]\n    count = 0\n    for x in nums:\n        if x >= 0:\n            k = math.isqrt(x)\n            if k * k == x:\n                count += 1\n    print(count)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <math.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        int count = 0;\n        for (int i = 0; i < n; i++) {\n            long long x;\n            if (scanf("%lld", &x) == 1) {\n                if (x >= 0) {\n                    long long k = (long long)sqrt(x);\n                    if (k * k == x) count++;\n                }\n            }\n        }\n        printf("%d\\n", count);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Duyệt qua từng số $a_i$ trong mảng, kiểm tra xem $a_i$ có thỏa mãn $(\\lfloor\\sqrt{a_i}\\rfloor)^2 == a_i$ hay không. Nếu có thì tăng biến đếm.\\n- **Độ phức tạp:** Thời gian $O(n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '5\n1 2 3 4 5\n', 'expected_output': '2\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Toàn bộ là chính phương', 'input_data': '4\n9 16 25 36\n', 'expected_output': '4\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Không có số chính phương nào', 'input_data': '3\n2 3 5\n', 'expected_output': '0\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Mảng 1 phần tử lớn 10^6', 'input_data': '1\n1000000\n', 'expected_output': '1\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Hỗn hợp nhiều số', 'input_data': '8\n10 16 20 25 30 49 64 80\n', 'expected_output': '4\n'}]}, {'id': 'DRAGON-77', 'title': 'Đếm #4 (Số Nguyên Tố Trong Dãy)', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào dãy $A$ có $n$ phần tử. Đếm xem trong dãy $A$ có bao nhiêu số là số nguyên tố.', 'input_format': 'Dòng 1: Số nguyên dương $n$ ($1 \\le n \\le 1000$).\\nDòng 2: $n$ số nguyên dương $a_i$ ($1 \\le a_i \\le 10^6$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra số lượng số nguyên tố có trong dãy $A$.', 'constraints': '$1 \\le n \\le 1000$\\n$1 \\le a_i \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '5\n1 2 3 4 5', 'sample_output': '3', 'hints': 'Viết một hàm kiểm tra số nguyên tố $O(\\sqrt{x})$, duyệt qua từng phần tử của dãy và đếm.', 'python_starter': "# Bí kíp luyện rồng - Đếm #4\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Đếm #4\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\nimport math\n\ndef is_prime(x):\n    if x < 2:\n        return False\n    if x in (2, 3):\n        return True\n    if x % 2 == 0 or x % 3 == 0:\n        return False\n    i = 5\n    while i * i <= x:\n        if x % i == 0 or x % (i + 2) == 0:\n            return False\n        i += 6\n    return True\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n = int(tokens[0])\n    nums = [int(x) for x in tokens[1:n+1]]\n    count = sum(1 for x in nums if is_prime(x))\n    print(count)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <stdbool.h>\n\nbool is_prime(long long x) {\n    if (x < 2) return false;\n    if (x == 2 || x == 3) return true;\n    if (x % 2 == 0 || x % 3 == 0) return false;\n    for (long long i = 5; i * i <= x; i += 6) {\n        if (x % i == 0 || x % (i + 2) == 0) return false;\n    }\n    return true;\n}\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        int count = 0;\n        for (int i = 0; i < n; i++) {\n            long long x;\n            if (scanf("%lld", &x) == 1) {\n                if (is_prime(x)) count++;\n            }\n        }\n        printf("%d\\n", count);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Với mỗi số $a_i \\le 10^6$, ta kiểm tra tính nguyên tố bằng cách duyệt các ước tới $\\sqrt{a_i}$. Vì $n \\le 1000$ và $\\sqrt{a_i} \\le 1000$, tổng số phép tính tối đa là $1000 \\times 1000 / 6 \\approx 1.6 \\times 10^5$, thực thi trong chưa đầy 5ms.\\n- **Độ phức tạp:** Thời gian $O(n \\sqrt{\\max A})$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '5\n1 2 3 4 5\n', 'expected_output': '3\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Không có số nguyên tố nào', 'input_data': '4\n1 4 6 8\n', 'expected_output': '0\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Toàn bộ là số nguyên tố', 'input_data': '3\n13 17 19\n', 'expected_output': '3\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Số 2 là nguyên tố chẵn duy nhất', 'input_data': '1\n2\n', 'expected_output': '1\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Dãy nhiều số nguyên tố lớn', 'input_data': '7\n11 23 29 31 37 41 43\n', 'expected_output': '7\n'}]}, {'id': 'DRAGON-78', 'title': 'Đếm #5 (Số May Mắn Trong Dãy)', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào dãy $A$ có $n$ phần tử. Đếm xem trong dãy $A$ có bao nhiêu số là số may mắn (số may mắn là số nguyên dương chia hết cho tổng các chữ số của nó).', 'input_format': 'Dòng 1: Số nguyên dương $n$ ($1 \\le n \\le 1000$).\\nDòng 2: $n$ số nguyên dương $a_i$ ($1 \\le a_i \\le 10^6$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra số lượng số may mắn trong dãy.', 'constraints': '$1 \\le n \\le 1000$\\n$1 \\le a_i \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '5\n1 12 3 14 5', 'sample_output': '4', 'hints': 'Với mỗi phần tử $x$, tính tổng các chữ số của $x$, sau đó kiểm tra xem $x \\% (\\text{tổng chữ số}) == 0$.', 'python_starter': "# Bí kíp luyện rồng - Đếm #5\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Đếm #5\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef is_lucky(x):\n    if x <= 0:\n        return False\n    temp = x\n    s = 0\n    while temp > 0:\n        s += temp % 10\n        temp //= 10\n    return s > 0 and (x % s == 0)\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n = int(tokens[0])\n    nums = [int(x) for x in tokens[1:n+1]]\n    count = sum(1 for x in nums if is_lucky(x))\n    print(count)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <stdbool.h>\n\nbool is_lucky(long long x) {\n    if (x <= 0) return false;\n    long long temp = x;\n    long long s = 0;\n    while (temp > 0) {\n        s += temp % 10;\n        temp /= 10;\n    }\n    return (s > 0 && x % s == 0);\n}\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        int count = 0;\n        for (int i = 0; i < n; i++) {\n            long long x;\n            if (scanf("%lld", &x) == 1) {\n                if (is_lucky(x)) count++;\n            }\n        }\n        printf("%d\\n", count);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Với mỗi phần tử $x$ trong dãy, ta tách từng chữ số của $x$ để tính tổng $S$. Nếu $x \\% S == 0$ thì $x$ là số Harshad (số may mắn), ta tăng biến đếm.\\n- **Độ phức tạp:** Thời gian $O(n \\log_{10}(\\max A))$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '5\n1 12 3 14 5\n', 'expected_output': '4\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Toàn bộ là số may mắn', 'input_data': '3\n10 18 20\n', 'expected_output': '3\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Không có số may mắn nào', 'input_data': '3\n11 13 17\n', 'expected_output': '0\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Số tròn trăm', 'input_data': '1\n100\n', 'expected_output': '1\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Nhiều số bội số của tổng chữ số', 'input_data': '6\n21 24 27 30 36 42\n', 'expected_output': '6\n'}]}, {'id': 'DRAGON-79', 'title': 'Tổng Ước Của Một Số', 'chapter': 'Phần V. Bài toán phân tích & Số học', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào một số nguyên dương $n$. Hãy tính và in ra tổng tất cả các ước số nguyên dương của $n$.', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 10^6$).', 'output_format': 'In ra một số nguyên duy nhất là tổng tất cả các ước của $n$.', 'constraints': '$1 \\le n \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '6', 'sample_output': '12', 'hints': 'Duyệt $i$ từ 1 đến $\\sqrt{n}$. Nếu $n \\% i == 0$, cộng $i$ và cả ước đối xứng $n / i$ (chú ý trường hợp $i == n / i$).', 'python_starter': "# Bí kíp luyện rồng - Tổng Ước\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Tổng Ước\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\nimport math\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    total = 0\n    limit = math.isqrt(n)\n    for i in range(1, limit + 1):\n        if n % i == 0:\n            total += i\n            if i * i != n:\n                total += n // i\n    print(total)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <math.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long total = 0;\n        long long limit = (long long)sqrt(n);\n        for (long long i = 1; i <= limit; i++) {\n            if (n % i == 0) {\n                total += i;\n                if (i * i != n) {\n                    total += n / i;\n                }\n            }\n        }\n        printf("%lld\\n", total);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Nếu $i$ là ước của $n$ thì $n/i$ cũng là ước của $n$. Do đó ta chỉ cần duyệt $i$ từ $1$ đến $\\sqrt{n}$. Khi tìm thấy $n \\% i == 0$, cộng cả $i$ và $n/i$ vào tổng (nếu $i = \\sqrt{n}$ thì chỉ cộng 1 lần).\\n- **Độ phức tạp:** Thời gian $O(\\sqrt{n})$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu n = 6)', 'input_data': '6\n', 'expected_output': '12\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test n = 1', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Số hoàn hảo 28', 'input_data': '28\n', 'expected_output': '56\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Số nguyên tố 13', 'input_data': '13\n', 'expected_output': '14\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Biên trên n = 10^6', 'input_data': '1000000\n', 'expected_output': '2480437\n'}]}, {'id': 'DRAGON-80', 'title': 'Đổi Giây Sang Giờ : Phút : Giây', 'chapter': 'Phần I. Phép toán số học & Định dạng', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 80 trong Bí kíp luyện rồng:\n\nNhập vào số nguyên dương $n$ là số giây ($1 \\le n \\le 80000$). Hãy đổi $n$ giây sang định dạng giờ, phút, giây.\n\nIn ra theo mẫu `xx:yy:zz` trong đó `xx` là số giờ, `yy` là số phút, `zz` là số giây (mỗi thành phần có đúng 2 chữ số, có số 0 ở đầu nếu giá trị < 10).', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 80000$).', 'output_format': 'In ra theo định dạng `xx:yy:zz`.', 'constraints': '$1 \\le n \\le 80000$.', 'sample_input': '4000', 'sample_output': '01:06:40', 'hints': 'Giờ = $n // 3600$, Phút = $(n \\% 3600) // 60$, Giây = $n \\% 60$. Dùng `%02d` trong C hoặc `{:02d}` trong Python.', 'python_starter': "# Bí kíp luyện rồng - Bài 80: Giờ : Phút : Giây\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 80: Giờ : Phút : Giây\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        n = int(line)\n        h = n // 3600\n        m = (n % 3600) // 60\n        s = n % 60\n        print(f"{h:02d}:{m:02d}:{s:02d}")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        int h = n / 3600;\n        int m = (n % 3600) / 60;\n        int s = n % 60;\n        printf("%02d:%02d:%02d\\n", h, m, s);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- 1 giờ = 3600 giây; 1 phút = 60 giây.\n- Số giờ: $h = \\lfloor n / 3600 \\rfloor$.\n- Số phút: $m = \\lfloor (n \\% 3600) / 60 \\rfloor$.\n- Số giây: $s = n \\% 60$.\n- In định dạng 2 chữ số dùng `%02d`.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu: 4000 -> 01:06:40)', 'input_data': '4000\n', 'expected_output': '01:06:40\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Đúng 1 giờ = 3600)', 'input_data': '3600\n', 'expected_output': '01:00:00\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (Giây nhỏ: 5 -> 00:00:05)', 'input_data': '5\n', 'expected_output': '00:00:05\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test đúng 1 ngày (86400 -> 24:00:00 hoặc 72000)', 'input_data': '72000\n', 'expected_output': '20:00:00\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test biên cực đại 80000', 'input_data': '80000\n', 'expected_output': '22:13:20\n'}]}, {'id': 'DRAGON-81', 'title': 'Ghép Số Và Đảo Ngược', 'chapter': 'Phần I. Xử lý chuỗi & Ký tự', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 81 trong Bí kíp luyện rồng:\n\nNhập vào hai số nguyên dương $a$ và $b$ ($1 \\le a, b \\le 10000$). Ghép 2 số $a$ và $b$ thành một chuỗi số $c$, sau đó in ra các chữ số của $c$ theo thứ tự ngược lại.', 'input_format': 'Hai số nguyên dương $a$ và $b$ cách nhau bởi 1 dấu cách.', 'output_format': 'In ra chuỗi số ghép được đảo ngược.', 'constraints': '$1 \\le a, b \\le 10000$.', 'sample_input': '34 56', 'sample_output': '6543', 'hints': 'Ghép `str(a) + str(b)`, sau đó đảo ngược chuỗi bằng slice `[::-1]`.', 'python_starter': "# Bí kíp luyện rồng - Bài 81: Ghép Số\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 81: Ghép Số\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    parts = sys.stdin.read().split()\n    if len(parts) >= 2:\n        c = parts[0] + parts[1]\n        print(c[::-1])\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char a[20], b[20];\n    if (scanf("%s %s", a, b) == 2) {\n        char c[50];\n        sprintf(c, "%s%s", a, b);\n        int len = strlen(c);\n        for (int i = len - 1; i >= 0; i--) {\n            putchar(c[i]);\n        }\n        putchar(\'\\n\');\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Ghép hai chuỗi số $a$ và $b$ thành chuỗi $c = a + b$.\n- In ra chuỗi $c$ từ ký tự cuối cùng về ký tự đầu tiên.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (34 56 -> 6543)', 'input_data': '34 56\n', 'expected_output': '6543\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (1 2 -> 21)', 'input_data': '1 2\n', 'expected_output': '21\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test có số 0 (10 20 -> 0201)', 'input_data': '10 20\n', 'expected_output': '0201\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test hai số giống nhau 123 123 -> 321321', 'input_data': '123 123\n', 'expected_output': '321321\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test số 10000 10000', 'input_data': '10000 10000\n', 'expected_output': '0000100001\n'}]}, {'id': 'DRAGON-82', 'title': 'Tích Lấy Dư Trong Đoạn [a, b]', 'chapter': 'Phần V. Bài toán phân tích & Số học', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào 3 số nguyên dương $a, b, c$. In ra số dư của phép chia tích các số nguyên trong đoạn $[a, b]$ cho $c$ (tức $(a \\times (a+1) \\times \\dots \\times b) \\pmod c$).', 'input_format': 'Một dòng chứa ba số nguyên dương $a, b, c$ ($1 \\le a \\le b \\le 10^5, 1 \\le c \\le 10^9$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra số dư tìm được.', 'constraints': '$1 \\le a \\le b \\le 10^5$\\n$1 \\le c \\le 10^9$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '5 10 11', 'sample_output': '5', 'hints': 'Nhân dồn từ $a$ đến $b$ và lấy modulo $c$ sau mỗi bước: `ans = (ans * i) % c`. Nếu `ans == 0` thì có thể dừng sớm.', 'python_starter': "# Bí kíp luyện rồng - Tích Lấy Dư\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Tích Lấy Dư\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    a, b, c = int(tokens[0]), int(tokens[1]), int(tokens[2])\n    ans = 1\n    for i in range(a, b + 1):\n        ans = (ans * (i % c)) % c\n        if ans == 0:\n            break\n    print(ans)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long a, b, c;\n    if (scanf("%lld %lld %lld", &a, &b, &c) == 3) {\n        long long ans = 1;\n        for (long long i = a; i <= b; i++) {\n            ans = (ans * (i % c)) % c;\n            if (ans == 0) break;\n        }\n        printf("%lld\\n", ans);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Áp dụng tính chất phân phối của phép nhân modulo: $(x \\times y) \\pmod c = ((x \\pmod c) \\times (y \\pmod c)) \\pmod c$. Vòng lặp chạy từ $a$ đến $b$. Nếu tại bất kỳ bước nào kết quả trung gian bằng 0 (chia hết cho $c$), ta có thể ngắt sớm để tiết kiệm thời gian.\\n- **Độ phức tạp:** Thời gian $O(b - a + 1) \\le 10^5$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 5..10 % 11)', 'input_data': '5 10 11\n', 'expected_output': '5\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Đoạn nhỏ 1..5 % 7', 'input_data': '1 5 7\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'a == b', 'input_data': '10 10 13\n', 'expected_output': '10\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Đoạn chứa c nên chia hết (mod = 0)', 'input_data': '1 100 97\n', 'expected_output': '0\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Đoạn lớn 1000..2000 modulo 10^9+7', 'input_data': '1000 2000 1000000007\n', 'expected_output': '649176378\n'}]}, {'id': 'DRAGON-83', 'title': 'Trọng Số Của Dãy Số', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Cho dãy số nguyên dương $A = (a_1, a_2, \\dots, a_n)$. Trọng số của dãy $A$ được tính theo công thức: $C = 1 \\times a_1 + 2 \\times a_2 + \\dots + n \\times a_n$. Hãy tính và in ra giá trị $C$.', 'input_format': 'Dòng 1: Số nguyên dương $n$ ($1 \\le n \\le 1000$).\\nDòng 2: $n$ số nguyên dương $a_i$ ($1 \\le a_i \\le 10^6$), cách nhau bởi khoảng trắng.', 'output_format': 'In ra một số nguyên là trọng số của dãy $A$.', 'constraints': '$1 \\le n \\le 1000$\\n$1 \\le a_i \\le 10^6$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '4\n4 3 2 5', 'sample_output': '36', 'hints': 'Sử dụng kiểu dữ liệu `long long` trong C để tránh tràn số vì tổng trọng số có thể đạt tới $1000 \\times 1000 \\times 10^6 / 2 \\approx 5 \\times 10^{11}$.', 'python_starter': "# Bí kíp luyện rồng - Trọng Số\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Trọng Số\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n = int(tokens[0])\n    nums = [int(x) for x in tokens[1:n+1]]\n    total = sum((i + 1) * nums[i] for i in range(n))\n    print(total)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        long long total = 0;\n        for (int i = 1; i <= n; i++) {\n            long long a;\n            if (scanf("%lld", &a) == 1) {\n                total += (long long)i * a;\n            }\n        }\n        printf("%lld\\n", total);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Duyệt vòng lặp từ $i = 1$ đến $n$, nhân chỉ số $i$ với phần tử $a_i$ và cộng dồn vào biến `total`. Chú ý dùng kiểu `long long` trong C vì kết quả có thể vượt quá $2 \\times 10^9$.\\n- **Độ phức tạp:** Thời gian $O(n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '4\n4 3 2 5\n', 'expected_output': '36\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Mảng 1 phần tử', 'input_data': '1\n100\n', 'expected_output': '100\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Toàn bộ là 1 (Tổng dãy tự nhiên)', 'input_data': '5\n1 1 1 1 1\n', 'expected_output': '15\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Mảng tăng dần', 'input_data': '3\n10 20 30\n', 'expected_output': '140\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Mảng nhiều phần tử', 'input_data': '6\n500 1000 1500 2000 2500 3000\n', 'expected_output': '42000\n'}]}, {'id': 'DRAGON-84', 'title': 'Chuyển Đổi Thập Phân Sang Nhị Phân', 'chapter': 'Phần I. Hệ cơ số', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 84 trong Bí kíp luyện rồng:\n\nNhập vào một số nguyên dương $n$ ở hệ thập phân ($1 \\le n \\le 10000$). Hãy chuyển đổi số $n$ sang hệ nhị phân và in ra kết quả.', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 10000$).', 'output_format': 'In ra chuỗi nhị phân biểu diễn số $n$.', 'constraints': '$1 \\le n \\le 10000$.', 'sample_input': '5', 'sample_output': '101', 'hints': 'Trong Python dùng `bin(n)[2:]`. Trong C chia liên tục cho 2, lưu các số dư vào mảng rồi in ngược lại.', 'python_starter': "# Bí kíp luyện rồng - Bài 84: Chuyển Số\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 84: Chuyển Số\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        n = int(line)\n        print(bin(n)[2:])\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        int bin[32];\n        int idx = 0;\n        while (n > 0) {\n            bin[idx++] = n % 2;\n            n /= 2;\n        }\n        for (int i = idx - 1; i >= 0; i--) {\n            printf("%d", bin[i]);\n        }\n        printf("\\n");\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Chia liên tục cho 2, số dư ở mỗi bước là các bit từ phải sang trái (LSB đến MSB).\n- In các số dư theo chiều ngược lại.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (5 -> 101)', 'input_data': '5\n', 'expected_output': '101\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Lũy thừa 2: 8 -> 1000)', 'input_data': '8\n', 'expected_output': '1000\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (1 -> 1)', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test 15 -> 1111', 'input_data': '15\n', 'expected_output': '1111\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test n = 10000 -> 10011100010000', 'input_data': '10000\n', 'expected_output': '10011100010000\n'}]}, {'id': 'DRAGON-85', 'title': 'Chuyển Số 2 (Nhị Phân Sang Thập Phân)', 'chapter': 'Phần VII. Xử lý chữ số', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': "Nhập vào số $n$ ở hệ nhị phân (gồm các ký tự '0' và '1'). Hãy chuyển số $n$ sang hệ thập phân và in ra màn hình.", 'input_format': 'Một dòng duy nhất chứa chuỗi ký tự nhị phân $n$ (độ dài chuỗi $\\le 60$).', 'output_format': 'In ra giá trị của số đó ở hệ thập phân.', 'constraints': 'Độ dài chuỗi nhị phân $\\le 60$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '101', 'sample_output': '5', 'hints': "Duyệt từng ký tự từ trái qua phải: `ans = ans * 2 + (ch - '0')`.", 'python_starter': "# Bí kíp luyện rồng - Chuyển Số 2\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Chuyển Số 2\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    print(int(line, 2))\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[100];\n    if (scanf("%s", s) == 1) {\n        unsigned long long ans = 0;\n        for (int i = 0; s[i] != \'\\0\'; i++) {\n            ans = ans * 2 + (s[i] - \'0\');\n        }\n        printf("%llu\\n", ans);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\\n- **Ý tưởng:** Đọc xâu nhị phân. Duyệt từ đầu đến cuối xâu, mỗi bước nhân giá trị tích lũy với 2 rồi cộng thêm giá trị chữ số hiện tại ($0$ hoặc $1$). Vì độ dài chuỗi $\\le 60$, kết quả chứa vừa vặn trong kiểu `unsigned long long` 64-bit trong C (tối đa tới $2^{64}-1$).\\n- **Độ phức tạp:** Thời gian $O(L)$ với $L$ là độ dài chuỗi, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 101)', 'input_data': '101\n', 'expected_output': '5\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test số 0', 'input_data': '0\n', 'expected_output': '0\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test 1111 (15)', 'input_data': '1111\n', 'expected_output': '15\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Lũy thừa của 2 (256)', 'input_data': '100000000\n', 'expected_output': '256\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Chuỗi dài (30 chữ số 1)', 'input_data': '111111111111111111111111111111\n', 'expected_output': '1073741823\n'}]}]
